{
  "findings": [
    {
      "title": "Contradiction: retreatment no longer an option vs. detailed retreatment section",
      "page": 58,
      "quote": "As of Amendment 7, retreatment is no longer an option (Section 7.1.6).",
      "severity": "critical"
    },
    {
      "title": "Contradiction: follow-up visits no longer required vs. detailed follow-up section",
      "page": 58,
      "quote": "As of Amendment 7, follow-up visits are no longer required (Section 7.1.4).",
      "severity": "critical"
    },
    {
      "title": "Inconsistent treatment duration: 96 weeks vs. 16 cycles of 6 weeks",
      "page": 58,
      "quote": "All patients currently on cemiplimab may continue treatment up to 96 weeks.",
      "severity": "major"
    },
    {
      "title": "Inconsistent cycle count in Extension Phase: EC16D22 implies 16 cycles but 96 weeks only allows 8 cycles",
      "page": 59,
      "quote": "Every 3 weeks, ±3 days (EC1D22 through EC16D22)",
      "severity": "major"
    },
    {
      "title": "Missing footnote for Table 3: no footnote for 'End of Extension Phase' column",
      "page": 59,
      "quote": "End of Extension Phase (up to 96 weeks)3",
      "severity": "minor"
    },
    {
      "title": "Inconsistent screening window: 45 days vs 28 days for informed consent",
      "page": 60,
      "quote": "must be obtained within 45 days prior to first dose of cemiplimab in the Extension Phase of the study. All screening assessments must be performed within 28 days prior to first dose",
      "severity": "minor"
    },
    {
      "title": "Inconsistent exclusion criterion #20: patients currently enrolled are excluded but then waived",
      "page": 58,
      "quote": "Exclusion criteria #20: Patients currently enrolled in R2810-ONC-1676 are not excluded.",
      "severity": "major"
    },
    {
      "title": "Inconsistent exclusion criterion #5: steroids for IC chemo not exclusionary but criterion says immunosuppressive doses excluded",
      "page": 58,
      "quote": "Exclusion criteria #5: Steroids applied as supportive medications for IC chemotherapy will not be exclusionary.",
      "severity": "major"
    },
    {
      "title": "Inconsistent PK sampling schedule: cycles 2-6, 7, 9, 11, 13, 15 vs. cycles 1-16",
      "page": 55,
      "quote": "PK samples are collected at pre-infusion and at the end of infusion on day 1 of cycles 2 through 6, 7, 9, 11, 13, and 15.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent ADA sampling schedule: cycles 1,3,7,11,15 vs. cycles 1-16",
      "page": 56,
      "quote": "The ADA samples for immunogenicity are collected pre-infusion on day 1 of cycle 1, 3, 7, 11, and 15.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent biomarker sampling: cycles 1-8 vs. cycles 1-16",
      "page": 56,
      "quote": "The biomarker samples are collected pre-infusion on day 1 of cycles 1 through 8.",
      "severity": "minor"
    },
    {
      "title": "Inconsistent PBMC sampling: cycles 1-3 vs. cycles 1-16",
      "page": 56,
      "quote": "If PBMC are collected, this sample should be collected prior to treatment on day 1 of cycles 1 through 3.",
      "severity": "minor"
    }
  ]
}
